package cli

import (
	"fmt"
	"os"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func decisionsCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "decisions",
		Short: "View and manage decisions for a feature",
	}

	cmd.AddCommand(decisionsListCmd())
	cmd.AddCommand(decisionsAckCmd())

	return cmd
}

func decisionsListCmd() *cobra.Command {
	var branch string
	var mine bool
	var all bool

	cmd := &cobra.Command{
		Use:   "show <feature>",
		Short: "List decisions for a feature (unread by default)",
		Args:  cobra.ExactArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		Run: func(cmd *cobra.Command, args []string) {
			feature := args[0]
			featurePath := internal.FeaturePath(feature)

			decisions, err := internal.LoadDecisions(featurePath)
			if err != nil {
				fmt.Printf("No decisions found for feature: %s\n", feature)
				return
			}

			if len(decisions.Entries) == 0 {
				fmt.Println("No decisions recorded yet.")
				return
			}

			// Auto-detect current branch for --mine and unread filtering
			myBranch := ""
			if b, err := currentBranch(); err == nil {
				myBranch = b
			}

			lastRead := 0
			if !all && myBranch != "" {
				lastRead = internal.LastReadID(featurePath, myBranch)
			}

			count := 0
			for _, entry := range decisions.Entries {
				if branch != "" && entry.Branch != branch {
					continue
				}
				if mine && myBranch != "" && !entry.IsRelevantTo(myBranch) {
					continue
				}
				if !all && myBranch != "" && entry.ID <= lastRead {
					continue
				}
				fmt.Println(entry)
				count++
			}

			if count == 0 {
				if all {
					fmt.Println("No decisions match filters.")
				} else {
					fmt.Println("No unread decisions. Use --all to see everything.")
				}
			}
		},
	}

	cmd.Flags().StringVar(&branch, "branch", "", "Filter by source branch")
	cmd.Flags().BoolVar(&mine, "mine", false, "Show only decisions relevant to current branch")
	cmd.Flags().BoolVar(&all, "all", false, "Show all decisions (including already read)")

	return cmd
}

func decisionsAckCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "ack <feature>",
		Short: "Mark all decisions as read for current branch",
		Args:  cobra.ExactArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		Run: func(cmd *cobra.Command, args []string) {
			feature := args[0]
			featurePath := internal.FeaturePath(feature)

			branch, err := currentBranch()
			if err != nil {
				fmt.Println("Error: could not detect current branch")
				os.Exit(1)
			}

			if err := internal.AckDecisions(featurePath, branch); err != nil {
				fmt.Printf("Error: %v\n", err)
				os.Exit(1)
			}

			fmt.Printf("Marked all decisions as read for branch: %s\n", branch)
		},
	}
}

package cli

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func openCmd() *cobra.Command {
	var useTmux bool
	var noTmux bool
	var noAgent bool

	cmd := &cobra.Command{
		Use:   "open [feature] [branch]",
		Short: "Open worktree and run agent",
		Long:  "Open a worktree and run the configured agent. With no args, shows an interactive picker.",
		Args:  cobra.RangeArgs(0, 2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return internal.ListBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		Run: func(cmd *cobra.Command, args []string) {
			feature, branch, err := resolveOpenArgs(args)
			if err != nil {
				fmt.Println(err)
				os.Exit(1)
			}

			path := internal.WorktreePath(feature, branch)

			if _, err := os.Stat(path); os.IsNotExist(err) {
				fmt.Printf("Worktree not found: %s\n", path)
				os.Exit(1)
			}

			// Re-sync inject files
			featurePath := internal.FeaturePath(feature)
			if err := internal.InjectFiles(featurePath, path); err != nil {
				fmt.Printf("Warning: inject sync failed: %v\n", err)
			}

			// Show unread decisions count
			unread := internal.UnreadDecisions(featurePath, branch)
			if len(unread) > 0 {
				targeted := 0
				for _, d := range unread {
					if d.To != "" {
						targeted++
					}
				}
				msg := fmt.Sprintf("  %d new decision(s)", len(unread))
				if targeted > 0 {
					msg += fmt.Sprintf(" (%d for you)", targeted)
				}
				msg += fmt.Sprintf(" (run: tws decisions show %s)", feature)
				fmt.Println(msg)
			}

			if noAgent {
				fmt.Printf("cd %s\n", path)
				fmt.Println("Run your agent manually from there.")
				return
			}

			// Resolve tmux preference
			tmux := useTmux
			if !cmd.Flags().Changed("tmux") && !noTmux {
				cfg := internal.LoadConfig()
				if cfg.UseTmux != nil {
					tmux = *cfg.UseTmux
				}
			}
			if noTmux {
				tmux = false
			}

			if tmux {
				openWithTmux(feature, branch, path)
			} else {
				// Warn if there's a stale tmux session
				session := sanitizeSessionName(feature + "/" + branch)
				if sessionExists(session) {
					fmt.Printf("Warning: tmux session %q exists for this worktree.\n", session)
					fmt.Printf("  Run 'tws close %s %s' to kill it, or use --tmux to attach.\n", feature, branch)
				}
				openDirect(path)
			}
		},
	}

	cmd.Flags().BoolVar(&useTmux, "tmux", false, "Wrap in tmux session")
	cmd.Flags().BoolVar(&noTmux, "no-tmux", false, "Skip tmux even if configured")
	cmd.Flags().BoolVar(&noAgent, "no-agent", false, "Just print the worktree path")

	return cmd
}

func resolveOpenArgs(args []string) (string, string, error) {
	var feature, branch string
	var err error

	switch len(args) {
	case 2:
		return args[0], args[1], nil
	case 1:
		feature = args[0]
		branches := internal.ListBranches(feature)
		if len(branches) == 0 {
			return "", "", fmt.Errorf("no branches found for feature: %s", feature)
		}
		branch, err = pick("Select branch:", branches)
		if err != nil {
			return "", "", err
		}
		return feature, branch, nil
	case 0:
		features := internal.ListFeatures()
		if len(features) == 0 {
			return "", "", fmt.Errorf("no features found. Use 'tws add <feature>' to create one")
		}
		feature, err = pick("Select feature:", features)
		if err != nil {
			return "", "", err
		}
		branches := internal.ListBranches(feature)
		if len(branches) == 0 {
			return "", "", fmt.Errorf("no branches found for feature: %s", feature)
		}
		branch, err = pick("Select branch:", branches)
		if err != nil {
			return "", "", err
		}
		return feature, branch, nil
	}
	return "", "", fmt.Errorf("unexpected args")
}

func openDirect(path string) {
	cfg := internal.LoadConfig()
	agentCmd := cfg.GetAgentCommand()

	if isClaudeAgent(agentCmd) && hasClaudeSession(path) {
		agentCmd = agentCmd + " -c"
	}

	parts := strings.Fields(agentCmd)
	if _, err := exec.LookPath(parts[0]); err != nil {
		fmt.Printf("Error: agent %q not found in PATH\n", parts[0])
		os.Exit(1)
	}

	fmt.Printf("Opening: %s\nRunning: %s\n", path, agentCmd)

	// Run agent as subprocess in the worktree directory
	agent := exec.Command(parts[0], parts[1:]...)
	agent.Dir = path
	agent.Stdin = os.Stdin
	agent.Stdout = os.Stdout
	agent.Stderr = os.Stderr

	if err := agent.Run(); err != nil {
		fmt.Printf("Agent exited: %v\n", err)
	}

	// Spawn an interactive shell in the worktree dir so the user stays there
	shell := os.Getenv("SHELL")
	if shell == "" {
		shell = "/bin/sh"
	}

	fmt.Printf("Dropped into shell at: %s\n", path)
	sh := exec.Command(shell)
	sh.Dir = path
	sh.Stdin = os.Stdin
	sh.Stdout = os.Stdout
	sh.Stderr = os.Stderr
	_ = sh.Run()
}

func openWithTmux(feature, branch, path string) {
	internal.RequireTool("tmux")

	session := sanitizeSessionName(feature + "/" + branch)

	if sessionExists(session) {
		fmt.Printf("Attaching to existing session: %s\n", session)
		internal.Must(internal.Run("tmux", "attach", "-t", session))
		return
	}

	cfg := internal.LoadConfig()
	agentCmd := cfg.GetAgentCommand()

	if isClaudeAgent(agentCmd) && hasClaudeSession(path) {
		agentCmd = agentCmd + " -c"
	}

	fmt.Printf("Creating tmux session: %s\n", session)
	internal.Must(internal.Run("tmux", "new-session", "-d", "-s", session, "-c", path))

	fmt.Printf("Running: %s\n", agentCmd)
	internal.Must(internal.Run("tmux", "send-keys", "-t", session, agentCmd, "Enter"))

	internal.Must(internal.Run("tmux", "attach", "-t", session))
}

func sessionExists(name string) bool {
	cmd := exec.Command("tmux", "has-session", "-t", name)
	err := cmd.Run()
	return err == nil
}

func sanitizeSessionName(s string) string {
	r := strings.NewReplacer(".", "_", ":", "_", "/", "-")
	return r.Replace(s)
}

func isClaudeAgent(cmd string) bool {
	base := strings.Fields(cmd)[0]
	return base == "claude" || base == "claude-dev" || base == "cc"
}

func hasClaudeSession(workdir string) bool {
	home, err := os.UserHomeDir()
	if err != nil {
		return false
	}

	absPath, err := filepath.Abs(workdir)
	if err != nil {
		return false
	}

	encoded := strings.ReplaceAll(absPath, string(filepath.Separator), "-")
	projectDir := filepath.Join(home, ".claude", "projects", encoded)

	info, err := os.Stat(projectDir)
	if err != nil {
		return false
	}
	return info.IsDir()
}

package internal

import (
	"fmt"
	"os"
	"path/filepath"
	"time"

	"gopkg.in/yaml.v3"
)

type Decision struct {
	ID        int    `yaml:"id"`
	Branch    string `yaml:"branch"`
	To        string `yaml:"to,omitempty"` // targeted recipient branch (empty = broadcast)
	Timestamp string `yaml:"timestamp"`
	Type      string `yaml:"type"` // breaking, info, deprecation, review, question
	Summary   string `yaml:"summary"`
	Details   string `yaml:"details,omitempty"`
}

type Decisions struct {
	Entries []Decision `yaml:"entries"`
}

func DecisionsPath(featurePath string) string {
	return filepath.Join(featurePath, "decisions.yaml")
}

func LoadDecisions(featurePath string) (Decisions, error) {
	data, err := os.ReadFile(DecisionsPath(featurePath))
	if err != nil {
		return Decisions{}, err
	}
	var d Decisions
	if err := yaml.Unmarshal(data, &d); err != nil {
		return Decisions{}, err
	}
	return d, nil
}

func SaveDecisions(featurePath string, d Decisions) error {
	data, err := yaml.Marshal(&d)
	if err != nil {
		return err
	}
	return os.WriteFile(DecisionsPath(featurePath), data, 0644)
}

func AddDecision(featurePath, branch, to, summary, decisionType, details string) (Decision, error) {
	decisions, _ := LoadDecisions(featurePath)

	// Auto-increment ID
	maxID := 0
	for _, e := range decisions.Entries {
		if e.ID > maxID {
			maxID = e.ID
		}
	}

	entry := Decision{
		ID:        maxID + 1,
		Branch:    branch,
		To:        to,
		Timestamp: time.Now().UTC().Format(time.RFC3339),
		Type:      decisionType,
		Summary:   summary,
		Details:   details,
	}

	decisions.Entries = append(decisions.Entries, entry)

	if err := SaveDecisions(featurePath, decisions); err != nil {
		return Decision{}, err
	}
	return entry, nil
}

func (d Decision) String() string {
	typeTag := fmt.Sprintf("[%s]", d.Type)
	target := ""
	if d.To != "" {
		target = fmt.Sprintf(" → %s", d.To)
	}
	s := fmt.Sprintf("#%d %s %s (%s%s, %s)", d.ID, typeTag, d.Summary, d.Branch, target, d.Timestamp)
	if d.Details != "" {
		s += fmt.Sprintf("\n    %s", d.Details)
	}
	return s
}

// IsRelevantTo returns true if a decision should be seen by the given branch.
// Broadcast decisions (empty To) are relevant to everyone.
// Targeted decisions are only relevant to the specified branch.
func (d Decision) IsRelevantTo(branch string) bool {
	if d.To == "" {
		return true // broadcast
	}
	return d.To == branch
}

// --- Read state tracking ---

type ReadState struct {
	Branches map[string]int `yaml:"branches"`
}

func readStatePath(featurePath string) string {
	return filepath.Join(featurePath, "read-state.yaml")
}

func LoadReadState(featurePath string) ReadState {
	data, err := os.ReadFile(readStatePath(featurePath))
	if err != nil {
		return ReadState{Branches: make(map[string]int)}
	}
	var rs ReadState
	if err := yaml.Unmarshal(data, &rs); err != nil {
		return ReadState{Branches: make(map[string]int)}
	}
	if rs.Branches == nil {
		rs.Branches = make(map[string]int)
	}
	return rs
}

func SaveReadState(featurePath string, rs ReadState) error {
	data, err := yaml.Marshal(&rs)
	if err != nil {
		return err
	}
	return os.WriteFile(readStatePath(featurePath), data, 0644)
}

// AckDecisions marks all current decisions as read for the given branch.
func AckDecisions(featurePath, branch string) error {
	decisions, err := LoadDecisions(featurePath)
	if err != nil {
		return err
	}

	maxID := 0
	for _, d := range decisions.Entries {
		if d.ID > maxID {
			maxID = d.ID
		}
	}

	rs := LoadReadState(featurePath)
	rs.Branches[branch] = maxID
	return SaveReadState(featurePath, rs)
}

// LastReadID returns the last read decision ID for a branch.
func LastReadID(featurePath, branch string) int {
	rs := LoadReadState(featurePath)
	return rs.Branches[branch]
}

// UnreadDecisions returns decisions relevant to a branch that haven't been acked.
func UnreadDecisions(featurePath, branch string) []Decision {
	decisions, err := LoadDecisions(featurePath)
	if err != nil {
		return nil
	}

	lastRead := LastReadID(featurePath, branch)

	var unread []Decision
	for _, d := range decisions.Entries {
		if d.ID > lastRead && d.IsRelevantTo(branch) {
			unread = append(unread, d)
		}
	}
	return unread
}
